function validate(input) {
  const [{ Transactions = [], Chargebacks = [] }] = input;
  const day = /^\d{4}-\d{2}-\d{2}$/;
  const dates = new Map();
  for (const row of Transactions) {
    if (row.some((v) => v === null)) return 'Transactions rows may not contain null.';
    const [id, , state, amount, date] = row;
    if (dates.has(id)) return `id ${id} appears twice in Transactions.`;
    if (state !== 'approved' && state !== 'declined') return `state ${state} is not approved or declined.`;
    if (amount < 0) return `Transaction ${id} has a negative amount.`;
    if (!day.test(date)) return `trans_date ${date} is not a YYYY-MM-DD date.`;
    dates.set(id, date);
  }
  for (const [id, date] of Chargebacks) {
    if (id === null || date === null) return 'Chargebacks rows may not contain null.';
    if (!dates.has(id)) return `A chargeback names unknown transaction ${id}.`;
    if (!day.test(date)) return `trans_date ${date} is not a YYYY-MM-DD date.`;
    if (date < dates.get(id)) return `The chargeback on ${id} predates its transaction.`;
  }
  return null;
}

