function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const iso = (t) => new Date(t).toISOString().slice(0, 10);
  const dayMs = 86400000, start = Date.UTC(2019, 4, 1);
  const countries = small ? ['US', 'DE'] : ['US', 'DE', 'FR', 'IN', 'BR', 'JP'];
  const count = small ? Math.floor(rand() * 9) : 2000;
  const Transactions = [];
  for (let i = 0; i < count; i++) {
    const when = start + Math.floor(rand() * (small ? 75 : 900)) * dayMs;
    const amount = small ? 1000 * (1 + Math.floor(rand() * 5)) : 1 + Math.floor(rand() * 10000);
    Transactions.push([(small ? 101 : 1) + i, pick(countries), rand() < 0.6 ? 'approved' : 'declined', amount, iso(when)]);
  }
  // At most one chargeback per transaction, filed 0 to 90 days later, often in a later month.
  const Chargebacks = [];
  for (const [id, , , , date] of Transactions) {
    if (rand() < (small ? 0.4 : 0.3)) Chargebacks.push([id, iso(Date.parse(`${date}T00:00:00Z`) + Math.floor(rand() * 91) * dayMs)]);
  }
  for (let i = Chargebacks.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Chargebacks[i], Chargebacks[j]] = [Chargebacks[j], Chargebacks[i]]; }
  return [{ Transactions, Chargebacks }];
}
